package __PACKAGE__;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.minecraft.resources.ResourceLocation;

/**
 * The settings of an emitter of a Sparkle system, in ticks and in blocks per tick (the files are in seconds and in
 * blocks per second: the game counts 20 ticks per second). Every setting of the file goes through
 * {@link #set(String, String, String)}, and a user parameter through {@link #setValue(String, String, double, double, double)}.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleEmitter implements Cloneable {
    public static final int POINT = 0;
    public static final int SPHERE = 1;
    public static final int BOX = 2;
    public static final int LINE = 3;

    public static final int DEATH = 0;
    public static final int TIME = 1;
    public static final int LOCATION = 2;
    public static final int COLLISION = 3;

    public static final int DIRECTION = 0;
    public static final int CONE = 1;
    public static final int RADIAL = 2;

    public static final int FIXED = 0;
    public static final int OVER_LIFE = 1;
    public static final int RANDOM = 2;

    /** Number used by the events. */
    public int id = 1;
    public int delay;
    public int duration = 40;
    /** Integer.MAX_VALUE: infinite. */
    public int loops = 1;
    public boolean burst = true;
    public int count = 30;
    public int shape = POINT;
    public double offsetX, offsetY, offsetZ;
    public double radius = 0.5;
    public double sizeX = 1.0, sizeY = 1.0, sizeZ = 1.0;
    /** Other end of the LINE shape (the offset is the first one). */
    public double lineX, lineY, lineZ = 5.0;
    public int lifetimeMin = 20, lifetimeMax = 30;
    public int direction = DIRECTION;
    public double directionX, directionY = 1.0, directionZ;
    /** Radians. */
    public double coneAngle = Math.toRadians(30.0);
    public double speedMin = 0.05, speedMax = 0.1;
    public boolean hasGravity = true;
    public double gravityX, gravityY = -9.8 / 400.0, gravityZ;
    public boolean collides;
    public double bounce = 0.4;
    public boolean diesOnCollision;
    public int scaleMode = FIXED;
    public float scaleValue = 0.2f, scaleStart = 0.3f, scaleEnd = 0.0f, scaleMin = 0.1f, scaleMax = 0.3f;
    public float red = 1.0f, green = 1.0f, blue = 1.0f;
    public boolean glow = true;
    public boolean translucent = true;
    /** The textures of the particles, in the particle atlas ("minecraft:glitter_7", "mymod:spark"). */
    public ResourceLocation[] textures = { ResourceLocation.tryParse("minecraft:glitter_7") };
    /** Several textures: the particle goes through them over its life (otherwise one at random). */
    public boolean animated;
    /** Chances (0-100) of the events; below 0: the event is not sent. */
    public double deathChance = -1.0, timeChance = -1.0, locationChance = -1.0, collisionChance = -1.0;
    private double deathChanceSet = 100.0, timeChanceSet = 100.0, locationChanceSet = 100.0, collisionChanceSet = 100.0;
    /** Age of the particle (ticks) when it sends its time event, or the interval between two. */
    public int timeTicks = 10;
    public boolean timeRepeats;
    public int zoneShape = SPHERE;
    public double zoneX, zoneY = 2.0, zoneZ;
    public double zoneRadius = 1.0;
    public double zoneSizeX = 2.0, zoneSizeY = 2.0, zoneSizeZ = 2.0;
    /** Emitter whose events spawn these particles; below 0: its own lifecycle. */
    public int eventSource = -1;
    private int eventSourceSet = 1;
    /** DEATH, TIME, LOCATION or COLLISION: the events of the source it receives. */
    public int eventType = DEATH;
    public int countPerEvent = 5;
    public boolean atDeath = true;
    /** Part of the speed of the particle that sent the event, 0 to 1. */
    public double inheritVelocity;

    /** A copy for a playing system, whose user parameters can change it. */
    public SparkleEmitter copy() {
        try {
            SparkleEmitter copy = (SparkleEmitter) clone();
            copy.textures = textures.clone();
            return copy;
        } catch (CloneNotSupportedException exception) {
            throw new IllegalStateException(exception);
        }
    }

    /** Switches a module on or off (the optional ones: gravity, collision, the events). */
    public void enable(String module, boolean enabled) {
        switch (module) {
            case "Gravity" -> hasGravity = enabled;
            case "Collision" -> collides = enabled;
            case "GenerateDeathEvent" -> deathChance = enabled ? deathChanceSet : -1.0;
            case "GenerateTimeEvent" -> timeChance = enabled ? timeChanceSet : -1.0;
            case "GenerateLocationEvent" -> locationChance = enabled ? locationChanceSet : -1.0;
            case "GenerateCollisionEvent" -> collisionChance = enabled ? collisionChanceSet : -1.0;
            case "ReceiveDeathEvent" -> eventSource = enabled ? eventSourceSet : -1;
            default -> {
            }
        }
    }

    /** A setting of the file, as written there ("2.5", "0 1 0", "Cone", "#FF8800", "true", "a;b"). */
    public void set(String module, String key, String text) {
        if (text == null) {
            return;
        }

        String value = text.trim();
        switch (module + "." + key) {
            case "Lifecycle.mode" -> {
                loopMode = value;
                updateLoops();
            }
            case "SpawnParticles.mode" -> burst = !value.equals("Continuous");
            case "SpawnParticles.shape" -> shape = switch (value) {
                case "Sphere" -> SPHERE;
                case "Box" -> BOX;
                case "Line" -> LINE;
                default -> POINT;
            };
            case "Velocity.mode" -> direction = switch (value) {
                case "Cone" -> CONE;
                case "Radial" -> RADIAL;
                default -> DIRECTION;
            };
            case "Scale.mode" -> scaleMode = switch (value) {
                case "OverLife" -> OVER_LIFE;
                case "Random" -> RANDOM;
                default -> FIXED;
            };
            case "Texture.texture" -> {
                List<ResourceLocation> list = new ArrayList<>();
                for (String part : value.split(";")) {
                    ResourceLocation location = part.isBlank() ? null : ResourceLocation.tryParse(part.trim().toLowerCase(Locale.ROOT));
                    if (location != null) {
                        list.add(location);
                    }
                }

                if (!list.isEmpty()) {
                    textures = list.toArray(new ResourceLocation[0]);
                }
            }
            case "Texture.spriteMode" -> animated = value.equals("OverLife");
            case "GenerateTimeEvent.mode" -> timeRepeats = value.equals("Repeat");
            case "GenerateLocationEvent.shape" -> zoneShape = value.equals("Box") ? BOX : SPHERE;
            case "ReceiveDeathEvent.event" -> eventType = switch (value) {
                case "Time" -> TIME;
                case "Location" -> LOCATION;
                case "Collision" -> COLLISION;
                default -> DEATH;
            };
            case "Texture.tint" -> {
                int rgb = color(value);
                setValue(module, key, (rgb >> 16 & 255) / 255.0, (rgb >> 8 & 255) / 255.0, (rgb & 255) / 255.0);
            }
            case "Collision.die", "Texture.glow", "Texture.translucent", "ReceiveDeathEvent.atDeath" ->
                setValue(module, key, value.equalsIgnoreCase("true") ? 1.0 : 0.0, 0.0, 0.0);
            default -> {
                double[] numbers = numbers(value);
                if (numbers != null) {
                    setValue(module, key, numbers[0], numbers[1], numbers[2]);
                }
            }
        }
    }

    /**
     * A number (x), a vector (x y z), a color (red green blue from 0 to 1) or a yes / no (1 or 0) of a setting, in the
     * units of the file: seconds, blocks per second, degrees, percents.
     */
    public void setValue(String module, String key, double x, double y, double z) {
        switch (module + "." + key) {
            case "Lifecycle.duration" -> duration = Math.max(1, ticks(x));
            case "Lifecycle.loops" -> {
                loopCount = Math.max(1, (int) Math.round(x));
                updateLoops();
            }
            case "Lifecycle.delay" -> delay = Math.max(0, ticks(x));
            case "Identity.id" -> id = (int) Math.round(x);
            case "SpawnParticles.count" -> count = Math.max(0, (int) Math.round(x));
            case "SpawnParticles.offset" -> {
                offsetX = x;
                offsetY = y;
                offsetZ = z;
            }
            case "SpawnParticles.radius" -> radius = Math.max(0.0, x);
            case "SpawnParticles.size" -> {
                sizeX = x;
                sizeY = y;
                sizeZ = z;
            }
            case "SpawnParticles.lineEnd" -> {
                lineX = x;
                lineY = y;
                lineZ = z;
            }
            case "SpawnParticles.lifetimeMin" -> lifetimeMin = Math.max(1, ticks(x));
            case "SpawnParticles.lifetimeMax" -> lifetimeMax = Math.max(1, ticks(x));
            case "Velocity.direction" -> {
                directionX = x;
                directionY = y;
                directionZ = z;
            }
            case "Velocity.angle" -> coneAngle = Math.toRadians(x);
            case "Velocity.speedMin" -> speedMin = x / 20.0;
            case "Velocity.speedMax" -> speedMax = x / 20.0;
            case "Gravity.acceleration" -> {
                gravityX = x / 400.0;
                gravityY = y / 400.0;
                gravityZ = z / 400.0;
            }
            case "Collision.bounce" -> bounce = Math.max(0.0, Math.min(1.0, x));
            case "Collision.die" -> diesOnCollision = x != 0.0;
            case "Scale.value" -> scaleValue = (float) x;
            case "Scale.start" -> scaleStart = (float) x;
            case "Scale.end" -> scaleEnd = (float) x;
            case "Scale.min" -> scaleMin = (float) x;
            case "Scale.max" -> scaleMax = (float) x;
            case "Texture.tint" -> {
                red = (float) x;
                green = (float) y;
                blue = (float) z;
            }
            case "Texture.glow" -> glow = x != 0.0;
            case "Texture.translucent" -> translucent = x != 0.0;
            case "GenerateDeathEvent.chance" -> deathChance = chance(deathChance, deathChanceSet = x);
            case "GenerateTimeEvent.chance" -> timeChance = chance(timeChance, timeChanceSet = x);
            case "GenerateLocationEvent.chance" -> locationChance = chance(locationChance, locationChanceSet = x);
            case "GenerateCollisionEvent.chance" -> collisionChance = chance(collisionChance, collisionChanceSet = x);
            case "GenerateTimeEvent.time" -> timeTicks = Math.max(1, ticks(x));
            case "GenerateLocationEvent.center" -> {
                zoneX = x;
                zoneY = y;
                zoneZ = z;
            }
            case "GenerateLocationEvent.radius" -> zoneRadius = Math.max(0.0, x);
            case "GenerateLocationEvent.size" -> {
                zoneSizeX = x;
                zoneSizeY = y;
                zoneSizeZ = z;
            }
            case "ReceiveDeathEvent.source" -> {
                eventSourceSet = (int) Math.round(x);
                eventSource = eventSource < 0 ? -1 : eventSourceSet;
            }
            case "ReceiveDeathEvent.count" -> countPerEvent = Math.max(1, (int) Math.round(x));
            case "ReceiveDeathEvent.atDeath" -> atDeath = x != 0.0;
            case "ReceiveDeathEvent.inheritVelocity" -> inheritVelocity = Math.max(0.0, Math.min(100.0, x)) / 100.0;
            default -> {
            }
        }
    }

    /** "Once", "Loop" or "Infinite", and the loops of the "Loop" mode (the settings come in any order). */
    private String loopMode = "Once";
    private int loopCount = 3;

    private void updateLoops() {
        loops = switch (loopMode) {
            case "Infinite" -> Integer.MAX_VALUE;
            case "Loop" -> loopCount;
            default -> 1;
        };
    }

    /** Lifetimes given the wrong way round are swapped once every setting is read. */
    public void finish() {
        if (lifetimeMax < lifetimeMin) {
            int lowest = lifetimeMax;
            lifetimeMax = lifetimeMin;
            lifetimeMin = lowest;
        }
    }

    private static double chance(double current, double value) {
        return current < 0.0 ? -1.0 : value;
    }

    private static int ticks(double seconds) {
        return (int) Math.round(seconds * 20.0);
    }

    /** "#RRGGBB" as 0xRRGGBB, white when it is not a color. */
    private static int color(String text) {
        String hex = text.startsWith("#") ? text.substring(1) : text;
        try {
            return hex.length() == 6 ? Integer.parseInt(hex, 16) : 0xFFFFFF;
        } catch (NumberFormatException exception) {
            return 0xFFFFFF;
        }
    }

    /** "2.5" or "0 1 0" (also "0, 1, 0"); null when it is not numbers. */
    private static double[] numbers(String text) {
        String[] parts = text.split("[\\s,;]+");
        double[] values = new double[3];
        int count = 0;
        for (String part : parts) {
            if (part.isEmpty()) {
                continue;
            }

            if (count >= 3) {
                return null;
            }

            try {
                values[count++] = Double.parseDouble(part);
            } catch (NumberFormatException exception) {
                return null;
            }
        }

        return count == 1 || count == 3 ? values : null;
    }
}
